$auditDirectory = Join-Path (Get-Location) 'artifacts/independent-v032'
$auditSource = Join-Path $auditDirectory 'source'
New-Item -ItemType Directory -Path $auditSource -Force | Out-Null
git archive --format=tar --output=artifacts/independent-v032/source.tar 2c9d0d2aa9f95336c449981d58d4360bc7d16d3f
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$archiveEntries = tar -tf artifacts/independent-v032/source.tar
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
if ($archiveEntries | Where-Object { $_ -match '(^/|^[A-Za-z]:|(^|/)\.\.(/|$))' }) { throw 'Unsafe archive entry' }
tar -xf artifacts/independent-v032/source.tar -C $auditSource
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $auditDirectory 'source.tar') | ConvertTo-Json

git -c core.autocrlf=false archive --format=tar --output=artifacts/independent-v032/source.tar 2c9d0d2aa9f95336c449981d58d4360bc7d16d3f
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
tar -xf artifacts/independent-v032/source.tar -C artifacts/independent-v032/source
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
node artifacts/independent-v032/verify.mjs

